import {derive,seal,open,createEnvelope,dateKey,monthCells,money,emptyData,validateData,validEnvelope,financeSummary,installmentInfo,recurringDue,shoppingLines,homeSections,changeHomeLayout,fuelStats,validateFuelRecord} from './core.js';
import {registerPasskey,protectPin,recoverPin,passkeyError} from './passkey.js';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>dateKey(new Date());
const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('sk-SK'):'';
const nav=[['home','⌂','Domov'],['calendar','▦','Kalendár'],['notes','✎','Poznámky'],['expenses','€','Financie'],['cards','▤','Vernostné karty'],['tasks','✓','Úlohy'],['shopping','▢','Nákupný zoznam'],['cars','◇','Moje auto'],['identities','▣','Doklady'],['files','▧','Dokumenty a fotky'],['passwords','⚿','Heslá'],['settings','⚙','Nastavenia']];
