const emojis={home:'🏠',calendar:'📅',notes:'📝',expenses:'💶',cards:'💳',tasks:'✅',shopping:'🛒',cars:'🚗',identities:'🪪',files:'📁',passwords:'🔐',settings:'⚙️',fuel:'⛽'};
const secure=['passwords','identities','files'];
const schemas={
 fuel:[['carId','Auto','cars',true],['title','Čerpacia stanica / názov','text'],['date','Dátum','date',true],['km','Stav kilometrov','number',true],['litres','Natankované litre','number',true],['amount','Celková cena (€)','number',true],['full','Natankované do plna','checkbox'],['missed','Chýba predošlé tankovanie — prerušiť výpočet','checkbox'],['text','Poznámka','textarea']],
 recurring:[['title','Čo platíš (byt, paušál, telefón…)','text',true],['kind','Typ platby','select',true,['Mesačná platba','Splátka']],['amount','Mesačne (€)','number',true],['day','Deň splatnosti (1–31)','number',true],['start','Začiatok evidencie','month',true],['balance','Celkom zostáva splatiť od začiatku evidencie (€)','number'],['end','Posledný mesiac (voliteľné)','month'],['category','Kategória','select',true,['Bývanie','Paušál','Predplatné','Úver','Elektronika','Auto','Poistenie','Ostatné']],['text','Poznámka','textarea']],
 income:[['title','Príjem / výplata','text',true],['amount','Suma (€)','number',true],['date','Dátum','date',true]],
 payments:[['title','Zaplatená pravidelná platba','text',true],['amount','Suma (€)','number',true],['date','Dátum','date',true]],
 notes:[['title','Názov','text',true],['category','Priečinok','text'],['text','Poznámka','textarea'],['pinned','Pripnúť','checkbox']],
 events:[['title','Udalosť','text',true],['date','Dátum','date',true],['time','Čas','time'],['category','Kategória','select',true,Object.keys(colors)],['color','Farba','color'],['text','Poznámka','textarea']],
 expenses:[['title','Kde / za čo','text',true],['amount','Suma (€)','number',true],['date','Dátum','date',true],['category','Kategória','select',true,['Potraviny','Bývanie','Doprava','Auto','Zábava','Zdravie','Ostatné']],['text','Poznámka','textarea']],
 cards:[['title','Obchod / názov karty','text',true],['number','Číslo karty','text'],['text','Poznámka','textarea'],['logo','Logo obchodu (PNG, JPG, WebP)','file'],['attachment','Fotka karty alebo čiarového kódu','file']],
 tasks:[['title','Úloha','text',true],['date','Termín','date'],['priority','Priorita','select',false,['Bežná','Vysoká','Nízka']],['text','Poznámka','textarea']],
 shoppingLists:[['title','Názov zoznamu','text',true],['items','Nové položky — každú na nový riadok','textarea']],
 shopping:[['title','Položka','text',true],['quantity','Množstvo','text'],['listId','Nákupný zoznam','shoppingLists',true]],
 cars:[['title','Názov auta','text',true],['plate','EČV','text'],['vin','VIN','text'],['km','Aktuálne kilometre','number'],['pzp','PZP platí do','date'],['insurance','Havarijné poistenie do','date'],['stk','STK do','date'],['ek','EK do','date'],['vignette','Diaľničná známka do','date'],['nextService','Ďalší servis (dátum)','date'],['nextKm','Ďalší servis pri km','number'],['text','Poznámka','textarea']],
 service:[['carId','Auto','cars',true],['title','Oprava / údržba / tankovanie','text',true],['date','Dátum','date',true],['km','Stav kilometrov','number'],['amount','Cena (€)','number'],['garage','Servis','text'],['text','Čo sa robilo','textarea'],['attachment','Faktúra alebo fotka','file']],
 passwords:[['title','Služba','text',true],['username','Prihlasovacie meno','text'],['password','Heslo','password',true],['url','Web','url'],['text','Poznámka','textarea']],
 identities:[['title','Doklad','text',true],['number','Číslo dokladu','text'],['date','Platnosť do','date'],['text','Poznámka','textarea'],['attachment','Predná strana','file'],['back','Zadná strana','file']],
 files:[['title','Názov','text',true],['category','Priečinok','text'],['text','Poznámka','textarea'],['attachment','Súbor / fotka','file',true]]
};
let shoppingListId=null,fuelCarId=null;
let faceRecord=null,faceBusy=false;
let mutationBusy=false;
let financeMonth=today().slice(0,7),financeTab='regular';
let db,envelope,data,key,vaultData,vaultKey,vaultSalt,page='home',query='',month=new Date(new Date().getFullYear(),new Date().getMonth(),1),epoch=0,lastActivity=Date.now(),writeQueue=Promise.resolve(),urls=[];
const store=async(mode,fn)=>new Promise((resolve,reject)=>{const tx=db.transaction('state',mode);let result;try{result=fn(tx.objectStore('state'));}catch(e){reject(e);return;}tx.oncomplete=()=>resolve(result?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Ukladanie sa nepodarilo.'));});
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function revoke(){urls.forEach(URL.revokeObjectURL);urls=[];}
function closeModal(){modal.close();modal.innerHTML='';revoke();}
// A queued close event may arrive after the dialog has reopened with new content.
modal.addEventListener('close',()=>{if(!modal.open){modal.innerHTML='';revoke();}});
function show(html){revoke();modal.innerHTML=html;if(!modal.open)modal.showModal();}
function lock(){epoch++;data=null;key=null;vaultData=null;vaultKey=null;vaultSalt=null;query='';closeModal();document.body.classList.remove('full-cal');renderAuth();}
async function persist(next=data, nextVault=vaultData){
 if(mutationBusy)throw Error('Prebieha ukladanie. Skús znova o chvíľu.');mutationBusy=true;
 const currentKey=key, salt=envelope.salt,vk=vaultKey,vs=vaultSalt,snapshot=structuredClone(next),vSnapshot=nextVault?structuredClone(nextVault):null;
 const operation=writeQueue.catch(()=>{}).then(async()=>{if(vSnapshot&&vk)snapshot.vault=await seal(vSnapshot,vk,vs);const encrypted=await seal(snapshot,currentKey,salt);await store('readwrite',s=>s.put(encrypted,'main'));envelope=encrypted;return snapshot;});
 writeQueue=operation;try{return await operation;}finally{mutationBusy=false;}
}
function authMarkup(setup){return `<div class="auth"><div class="brandbox"><span class="brand">FSB</span></div><div class="eyebrow">Tvoj osobný priestor</div><h1>${setup?'Všetko dôležité. Na jednom mieste.':'Vitaj späť.'}</h1><p class="muted">${setup?'Vytvor si 6-ciferný PIN pre tento iPhone.':'Odomkni svoj deň.'}</p><form id="authForm"><label for="pin">${setup?'Nový PIN':'Tvoj PIN'}</label><input id="pin" name="pin" class="pin-input" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="off" required>${setup?'<label for="confirmPin">Zopakuj PIN</label><input id="confirmPin" name="confirm" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required>':''}<p class="error" id="authError" role="alert"></p><button class="gold">${setup?'Vytvoriť môj priestor':'Odomknúť'}</button></form><small>Údaje ostávajú v tomto prehliadači. PIN nie je obnoviteľný. Pre citlivé údaje je vo vnútri samostatný trezor.</small>${setup?'<button data-action="restore" class="quiet" style="margin-top:20px">Obnoviť zo zálohy</button>':''}${!setup&&faceRecord?'<button data-action="faceUnlock" style="width:100%;margin-top:20px">◎ Odomknúť cez Face ID</button>':'<small>Face ID môžeš zapnúť po odomknutí v Nastaveniach.</small>'}</div>`;}
function renderAuth(){app.innerHTML=authMarkup(!envelope);$('#authForm').onsubmit=async e=>{e.preventDefault();if(faceBusy)return;const form=e.currentTarget,secret=form.pin.value,token=epoch;form.querySelector('button').disabled=true;try{if(!envelope){if(secret!==form.confirm.value)throw Error('PIN-y sa nezhodujú.');const result=await createEnvelope(emptyData(),secret);await store('readwrite',s=>s.put(result.envelope,'main'));envelope=result.envelope;if(token!==epoch)return;key=result.key;data=emptyData();}else{const k=await derive(secret,envelope.salt);const decoded=validateData(await open(envelope,k));if(token!==epoch)return;key=k;data=decoded;}form.reset();lastActivity=Date.now();page='home';render();navigator.storage?.persist?.().catch(()=>{});}catch(err){if(token===epoch){$('#authError').textContent=err.message==='PIN-y sa nezhodujú.'?err.message:'Nesprávny PIN alebo údaje nie sú dostupné. Skús znova.';form.querySelector('button').disabled=false;}}};}
function getRecords(type){return secure.includes(type)?vaultData?.[type]||[]:data[type]||[];}
function title(type){return nav.find(n=>n[0]===type)?.[2]||({events:'Udalosti',service:'Servisný záznam',recurring:'Pravidelné platby',income:'Príjem',payments:'Zaplatená platba',shoppingLists:'Nákupný zoznam',fuel:'Tankovanie'}[type])||type;}
function icon(type){return nav.find(n=>n[0]===type)?.[1]||'◷';}
function button(type){return `<button class="tile" data-page="${type}"><span class="icon tile-emoji" aria-hidden="true">${emojis[type]||icon(type)}</span><span>${title(type)}</span><small>${secure.includes(type)?'Chránený trezor':type==='calendar'?'Tvoj plán':type==='settings'?'Záloha a zabezpečenie':getRecords(type).length+' záznamov'}</small></button>`;}
function reminders(){const list=[];for(const c of data.cars){for(const [field,label]of [['pzp','PZP'],['insurance','Havarijné poistenie'],['stk','STK'],['ek','EK'],['vignette','Diaľničná známka'],['nextService','Servis']])if(c[field])list.push({date:c[field],title:`${c.title} · ${label}`,type:'cars'});if(c.nextKm&&Number(c.km)>=Number(c.nextKm))list.push({date:today(),title:`${c.title} · dosiahnutý servisný interval`,type:'cars'});}return list.filter(r=>r.date<=dateKey(new Date(Date.now()+30*86400000))).sort((a,b)=>a.date.localeCompare(b.date));}
function expenseRows(){return [...data.expenses,...(data.fuel||[]).map(r=>({...r,category:'Tankovanie',source:'fuel'})),...(data.payments||[]).map(r=>({...r,category:r.category||'Pravidelné platby',source:'payments'})),...data.service.filter(s=>Number(s.amount)>0).map(s=>({...s,category:'Auto',source:'service'}))];}
function monthTotal(m=today().slice(0,7)){return expenseRows().filter(r=>r.date?.startsWith(m)).reduce((a,b)=>a+Number(b.amount||0),0);}
function home(){const events=data.events.filter(e=>e.date===today());const totals=financeSummary(data,today().slice(0,7));return `<div class="eyebrow">${new Date().toLocaleDateString('sk-SK',{weekday:'long',day:'numeric',month:'long'})}</div><h1>Filip S. Belan</h1><div class="stats home-stats"><div class="stat"><small>Dnes v kalendári</small><strong>${events.length}</strong></div><div class="stat"><small>Príjem</small><strong title="${money(totals.income)}">${compactMoney(totals.income)}</strong></div><div class="stat"><small>Výdavky</small><strong title="${money(totals.spent)}">${compactMoney(totals.spent)}</strong></div><div class="stat"><small>Zostáva</small><strong class="${totals.available<0?'negative':''}" title="${money(totals.available)}">${compactMoney(totals.available)}</strong></div></div><p class="month-caption">Financie za ${new Date().toLocaleDateString('sk-SK',{month:'long',year:'numeric'})} · zostáva = príjem − zaplatené výdavky</p><div class="tiles">${homeSections(data.homeLayout,nav.filter(n=>n[0]!=='home').map(n=>n[0])).order.filter(id=>!homeSections(data.homeLayout,nav.filter(n=>n[0]!=='home').map(n=>n[0])).hidden.includes(id)).map(id=>button(id)).join('')}</div>`;}
function compactMoney(n){return new Intl.NumberFormat('sk-SK',{notation:Math.abs(n)>=10000?'compact':'standard',maximumFractionDigits:Math.abs(n)>=10000?1:0}).format(n)+' €';}
function calendar(){const cells=monthCells(month.getFullYear(),month.getMonth());return `<div class="calendar-page"><div class="row between"><div><div class="eyebrow">Priestor pre tvoje plány</div><h1>Kalendár</h1></div><button data-action="fullscreen" aria-label="Rozšíriť kalendár">⛶</button></div><div class="row between calendar-head"><button data-action="prev" aria-label="Predchádzajúci mesiac">‹</button><h2>${month.toLocaleDateString('sk-SK',{month:'long',year:'numeric'})}</h2><button data-action="next" aria-label="Nasledujúci mesiac">›</button></div><div class="row between"><button class="quiet" data-action="today">Dnes</button><button class="gold" data-action="new" data-type="events">＋ Udalosť</button></div><div class="week">${['Po','Ut','St','Št','Pi','So','Ne'].map(d=>`<div>${d}</div>`).join('')}</div><div class="month">${cells.map(d=>{const ev=data.events.filter(e=>e.date===d.date).sort((a,b)=>(a.time||'').localeCompare(b.time||''));return `<button class="day ${d.current?'':'out'} ${d.date===today()?'today':''}" data-action="day" data-date="${d.date}" aria-label="${fmt(d.date)}, ${ev.length} udalostí"><span class="num">${d.day}</span>${ev.slice(0,3).map(e=>`<span class="event" style="--event:${safeColor(e.color||colors[e.category])}">${esc(e.title)}</span>`).join('')}${ev.length>3?`<span class="mini">+${ev.length-3} ďalšie</span>`:''}</button>`;}).join('')}</div></div>`;}
const safeColor=c=>/^#[0-9a-f]{6}$/i.test(c)?c:'#d4b577';
function record(type,r){let summary=r.text||'';if(['income','payments','recurring'].includes(type))summary=`${money(r.amount)} · ${r.date?fmt(r.date):r.category||''}`;if(type==='expenses')summary=`${fmt(r.date)} · ${r.category||'Ostatné'}`;if(type==='events')summary=`${fmt(r.date)} ${r.time||''} · ${r.category}`;if(type==='cards')summary=r.number||'Karta pripravená';if(type==='shopping')summary=`${r.quantity||''} ${r.category?'· '+r.category:''}`;if(type==='tasks')summary=`${r.date?fmt(r.date)+' · ':''}${r.priority||'Bežná'}`;if(type==='cars')summary=`${r.plate||''} · ${Number(r.km||0).toLocaleString('sk-SK')} km`;if(type==='fuel')summary=`${fmt(r.date)} · ${data.cars.find(c=>c.id===r.carId)?.title||'Auto'} · ${r.litres} l · ${money(r.amount)} · ${r.full?'Plná nádrž':'Čiastočne'}`;if(type==='service')summary=`${fmt(r.date)} · ${data.cars.find(c=>c.id===r.carId)?.title||'Auto'} · ${money(r.amount)}`;if(type==='identities')summary=r.date?'Platnosť do '+fmt(r.date):'Bez dátumu platnosti';if(type==='passwords')summary=r.username||'Uložené v trezore';return `<article class="record card open-record ${r.done?'done':''}" data-open="${type}" data-id="${esc(r.id)}">${['tasks','shopping'].includes(type)?`<input type="checkbox" aria-label="Dokončiť ${esc(r.title)}" data-action="toggle" data-type="${type}" data-id="${esc(r.id)}" ${r.done?'checked':''}>`:''}<button class="record-open" data-action="view" data-type="${type}" data-id="${esc(r.id)}"><span class="icon" aria-hidden="true">${emojis[type]||icon(type)}</span><span class="body"><span class="record-title">${r.pinned?'⌑ ':''}${esc(r.title)}</span><span class="record-summary">${esc(summary.slice(0,160))}</span>${type==='expenses'?`<strong class="amount">${money(r.amount)}</strong>`:''}</span><span class="record-arrow" aria-hidden="true">›</span></button></article>`;}

function finance(){
 const m=financeMonth,t=financeSummary(data,m),payments=data.payments||[];
 const rows=(data.recurring||[]).filter(r=>financeTab==='installments'?r.kind==='Splátka':r.kind!=='Splátka');
 const active=rows.filter(r=>r.start<=m&&(!r.end||r.end>=m)),other=rows.filter(r=>!active.includes(r));
 const match=r=>Object.values(r).filter(v=>typeof v==='string').join(' ').toLowerCase().includes(query.toLowerCase());
 const list=financeTab==='income'?(data.income||[]).filter(r=>r.date?.startsWith(m)&&match(r)).map(r=>({...r,recordType:'income'})):[...(data.fuel||[]).map(r=>({...r,recordType:'fuel'})),...data.expenses.map(r=>({...r,recordType:'expenses'})),...data.service.filter(r=>Number(r.amount)>0).map(r=>({...r,recordType:'service'}))].filter(r=>r.date?.startsWith(m)&&match(r));
 list.sort((a,b)=>(b.date||'').localeCompare(a.date||''));
 const tabNames={regular:'Platby',installments:'Splátky',purchases:'Nákupy',income:'Príjmy'};
 const addType=financeTab==='income'?'income':financeTab==='purchases'?'expenses':'recurring';
 const addLabel=financeTab==='income'?'Pridať príjem':financeTab==='purchases'?'Zapísať nákup':financeTab==='installments'?'Pridať splátku':'Pridať platbu';
 return `<div class="row between wrap"><div><div class="eyebrow">Tvoje peniaze, prehľadne</div><h1>Financie</h1></div><input id="financeMonth" type="month" value="${esc(m)}" aria-label="Vybrať mesiac" style="width:165px"></div><section class="hero budget-summary"><small>Zostáva teraz</small><h2 class="${t.available<0?'negative':''}">${money(t.available)}</h2><p class="muted">Po zostávajúcich platbách: <strong class="${t.afterBills<0?'negative':''}">${money(t.afterBills)}</strong></p><div class="budget-numbers"><div><small>Príjem</small><strong>${money(t.income)}</strong></div><div><small>Zaplatené</small><strong>${money(t.spent)}</strong></div><div><small>Ešte zaplatiť</small><strong>${money(t.due)}</strong></div></div><div class="row wrap finance-quick"><button class="gold" data-action="new" data-type="expenses">− Zapísať výdavok</button><button data-action="new" data-type="income">＋ Príjem</button></div><details class="budget-explain"><summary>Ako sa počíta zostatok?</summary><p>Teraz zostáva ${money(t.available)}. Po odložení ${money(t.due)} na ešte neuhradené platby ostane ${money(t.afterBills)}. Počítajú sa záznamy v appke vrátane servisu a tankovania auta, nie bankový účet.</p></details></section><div class="finance-tabs" role="tablist" aria-label="Financie">${Object.entries(tabNames).map(([id,name])=>`<button role="tab" aria-selected="${financeTab===id}" class="${financeTab===id?'active':''}" data-action="financeTab" data-tab="${id}">${name}</button>`).join('')}</div><div class="row between wrap section-heading"><h2>${financeTab==='regular'?'Mesačné platby':financeTab==='installments'?'Čo ešte splácaš':financeTab==='income'?'Príjmy v mesiaci':'Nákupy a výdavky'}</h2><button data-action="new" data-type="${addType}" ${financeTab==='installments'?'data-kind="Splátka"':''}>＋ ${addLabel}</button></div>${['regular','installments'].includes(financeTab)?`<p class="muted finance-hint">${financeTab==='regular'?'Byt, paušál či predplatné nastavíš raz. Každý mesiac len označ úhradu.':'Telefón, Mac, hodinky či auto. Zostatok sa zníži až po označení úhrady.'}</p>${active.length?active.map(r=>billCard(r,m)).join(''):`<div class="empty"><h3>${financeTab==='installments'?'Zatiaľ žiadne splátky':'Zatiaľ žiadne mesačné platby'}</h3><p>${financeTab==='installments'?'Zadaj mesačnú sumu a koľko ti ostáva splatiť.':'Pridaj prvú platbu a deň splatnosti.'}</p></div>`}${other.length?`<details class="card"><summary>Ukončené a budúce (${other.length})</summary>${other.map(r=>billCard(r,m)).join('')}</details>`:''}${financeTab==='regular'?`<details class="payment-history"><summary>História úhrad v mesiaci</summary>${payments.filter(r=>r.month===m).map(r=>record('payments',r)).join('')||'<p class="muted">Žiadne zaznamenané úhrady.</p>'}</details>`:''}`:`<div class="search"><input id="search" type="search" placeholder="Hľadať…" aria-label="Hľadať v záznamoch" value="${esc(query)}"></div>${list.length?list.map(r=>record(r.recordType,r)).join(''):'<div class="empty"><p>Zatiaľ tu nemáš žiadne záznamy.</p></div>'}`}`;
}
function billCard(r,m){
 const payment=data.payments.find(p=>p.recurringId===r.id&&p.month===m),isInstallment=r.kind==='Splátka',info=isInstallment?installmentInfo(r,data.payments,m):null,due=recurringDue(r,data.payments,m),completed=isInstallment&&info.remaining===0;
 const enabled=r.start<=m&&(!r.end||r.end>=m),day=Math.min(Number(r.day)||1,new Date(Number(m.slice(0,4)),Number(m.slice(5)),0).getDate());
 return `<article class="card bill-card" data-open="recurring" data-id="${esc(r.id)}"><div class="row between"><div><h3>${esc(r.title)}</h3><small>${esc(r.category||'Platba')} · ${day}. deň v mesiaci</small></div><button class="quiet" data-action="view" data-type="recurring" data-id="${esc(r.id)}" aria-label="Detail ${esc(r.title)}">⋯</button></div><div class="row between bill-amount"><strong>${money(payment?.amount??(due||r.amount))}<small> / mesiac</small></strong>${payment?`<button class="paid" data-action="unpay" data-id="${esc(payment.id)}" aria-label="Vrátiť ${esc(r.title)} na neuhradené">✓ Uhradené ↶</button>`:enabled&&due>0?`<button class="gold" data-action="pay" data-id="${esc(r.id)}">Označiť úhradu</button>`:`<span class="tag">${completed?'Splatené':enabled?'Bez platby':'Mimo obdobia'}</span>`}</div>${isInstallment?`<div class="installment-progress"><div class="row between"><span>Zostáva <b>${money(info.remaining)}</b></span><small>${info.count} splátok</small></div><progress value="${info.percent}" max="100" aria-label="Splatené ${info.percent} percent"></progress><small>Uhradené ${money(info.paid)} z ${money(info.total)} od ${esc(r.start)}</small></div>`:''}</article>`;
}
function safeImage(a){return a&&['image/png','image/jpeg','image/webp'].includes(a.type)&&new RegExp('^data:'+a.type+';base64,[A-Za-z0-9+/=]+$').test(a.data||'')?a.data:null;}
function visualPage(type){
 const rows=getRecords(type).filter(r=>[r.title,r.category,r.number,r.text].filter(Boolean).join(' ').toLowerCase().includes(query.toLowerCase()));
 const heading=`<div class="row between"><h1>${title(type)}</h1><button class="gold" data-action="new" data-type="${type}">＋ Pridať</button></div>${secure.includes(type)?'<button class="quiet" data-action="vaultLock">🔒 Zamknúť trezor</button>':''}<div class="search"><input id="search" type="search" aria-label="Hľadať" placeholder="Hľadať…" value="${esc(query)}"></div>`;
 if(!rows.length)return heading+'<div class="empty"><p>'+ (query?'Žiadne výsledky.':'Pridaj svoj prvý záznam.')+'</p></div>';
 if(type==='cards')return heading+`<div class="loyalty-grid">${rows.map(r=>`<button class="loyalty-card" data-action="view" data-type="cards" data-id="${esc(r.id)}">${safeImage(r.logo)?`<img src="${esc(safeImage(r.logo))}" alt="" class="loyalty-logo">`:'<span class="logo-placeholder">💳</span>'}<span>${esc(r.title)}</span></button>`).join('')}</div>`;
 if(type==='identities')return heading+`<div class="identity-grid">${rows.map(r=>{const expired=r.date&&r.date<today();const near=r.date&&r.date<=dateKey(new Date(Date.now()+30*86400000));return `<button class="identity-card" data-action="view" data-type="identities" data-id="${esc(r.id)}"><span class="row between"><span class="document-icon">🪪</span><span class="tag ${expired?'expired':near?'soon':''}">${r.date?(expired?'Po platnosti':near?'Čoskoro končí':'Platný'):'Bez dátumu'}</span></span><strong>${esc(r.title)}</strong>${r.number?`<span class="muted">•••• ${esc(r.number.slice(-4))}</span>`:''}<span class="identity-date">${r.date?'Platnosť do '+fmt(r.date):'Doplň dátum platnosti'}</span><span class="mini muted">${r.attachment?'Predná strana ✓':'Predná strana —'} · ${r.back?'Zadná strana ✓':'Zadná strana —'}</span></button>`;}).join('')}</div>`;
 const groups=[...new Set(rows.map(r=>r.category||'Bez priečinka'))];
 return heading+groups.map(group=>`<section class="file-section"><h2>📂 ${esc(group)}</h2><div class="file-grid">${rows.filter(r=>(r.category||'Bez priečinka')===group).map(r=>`<button class="file-card" data-action="view" data-type="files" data-id="${esc(r.id)}"><span class="file-preview">${safeImage(r.attachment)?`<img loading="lazy" src="${esc(safeImage(r.attachment))}" alt="">`:`<span>${r.attachment?.type==='application/pdf'?'📄':'🖼️'}</span>`}</span><strong>${esc(r.title)}</strong><small>${esc(r.attachment?.name||'Bez súboru')}</small></button>`).join('')}</div></section>`).join('');
}
function shoppingPage(){
 if(shoppingListId&&data.shoppingLists.some(l=>l.id===shoppingListId))return shoppingDetail(shoppingListId);
 shoppingListId=null;
 const lists=data.shoppingLists.filter(l=>(l.title+' '+data.shopping.filter(i=>i.listId===l.id).map(i=>i.title).join(' ')).toLowerCase().includes(query.toLowerCase()));
 return `<div class="row between"><h1>Nákupné zoznamy</h1><button class="gold" data-action="new" data-type="shoppingLists">＋ Zoznam</button></div><div class="search"><input id="search" type="search" aria-label="Hľadať nákup" placeholder="Zoznam alebo položka…" value="${esc(query)}"></div><div class="shopping-lists">${lists.map(l=>{const items=data.shopping.filter(i=>i.listId===l.id),done=items.filter(i=>i.done).length;return `<button class="shopping-list-card" data-action="view" data-type="shoppingLists" data-id="${esc(l.id)}"><span class="row between"><span class="document-icon">🛒</span><span class="tag">${done} / ${items.length}</span></span><strong>${esc(l.title)}</strong><span class="muted">${esc(items.filter(i=>!i.done).slice(0,3).map(i=>i.title).join(', ')||'Všetko vybavené')}</span><progress max="${Math.max(items.length,1)}" value="${done}"></progress></button>`;}).join('')||'<div class="empty"><p>Vytvor zoznam a pridaj viac položiek naraz.</p></div>'}</div>`;
}
function shoppingDetail(id){const list=data.shoppingLists.find(l=>l.id===id);if(!list)return '';const items=data.shopping.filter(i=>i.listId===id).sort((a,b)=>Number(!!a.done)-Number(!!b.done));return `<div class="row between"><h2>🛒 ${esc(list.title)}</h2><button data-action="shoppingBack">← Zoznamy</button></div><p class="muted">${items.filter(i=>i.done).length} z ${items.length} hotových</p>${items.map(i=>record('shopping',i)).join('')||'<p class="muted">Pridaj prvé položky.</p>'}<div class="form-actions"><button class="gold" data-action="edit" data-type="shoppingLists" data-id="${esc(id)}">＋ Položky / upraviť zoznam</button><button class="danger" data-action="delete" data-type="shoppingLists" data-id="${esc(id)}">Vymazať zoznam</button></div>`;}
function shoppingView(id){if(!data.shoppingLists.some(l=>l.id===id))return;shoppingListId=id;page='shopping';query='';closeModal();render();window.scrollTo(0,0);}
function fuelSection(){
 if(!data.cars.length)return '';
 const car=data.cars.find(c=>c.id===fuelCarId)||data.cars[0];fuelCarId=car.id;
 const rows=(data.fuel||[]).filter(r=>r.carId===car.id).sort((a,b)=>b.date.localeCompare(a.date)||Number(b.km)-Number(a.km));
 const stats=fuelStats(data.fuel||[],car.id),monthly=rows.filter(r=>r.date.startsWith(today().slice(0,7))).reduce((n,r)=>n+Number(r.amount),0),num=n=>Number(n).toLocaleString('sk-SK',{maximumFractionDigits:2});
 return `<section class="fuel-section"><div class="row between wrap"><h2>⛽ Tankovanie a spotreba</h2><button class="gold" data-action="new" data-type="fuel">＋ Tankovanie</button></div><label for="fuelCar">Vybrať auto</label><select id="fuelCar">${data.cars.map(c=>`<option value="${esc(c.id)}" ${c.id===car.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select><div class="stats"><div class="stat"><small>Priemerná spotreba</small><strong>${stats.consumption===null?'—':num(stats.consumption)+' l'}</strong><small>na 100 km</small></div><div class="stat"><small>Tento mesiac</small><strong>${money(monthly)}</strong><small>tankovanie</small></div><div class="stat"><small>Náklady / 100 km</small><strong>${stats.costPer100===null?'—':money(stats.costPer100)}</strong><small>uzavreté intervaly</small></div></div><p class="muted finance-hint">${stats.consumption===null?'Pre výpočet spotreby zaznamenaj aspoň dve plné nádrže. Medzi nimi zapíš aj všetky čiastočné tankovania.':`Vypočítané z ${num(stats.distance)} km medzi plnými nádržami.`} Náklady sa automaticky započítajú do financií.</p>${stats.intervals.length?`<details><summary>Spotreba medzi tankovaniami</summary><div class="list">${[...stats.intervals].reverse().map(i=>`<div class="card row between"><span>${fmt(i.from)} – ${fmt(i.to)}<br><small>${num(i.distance)} km · ${num(i.litres)} l</small></span><strong>${num(i.consumption)} l/100 km</strong></div>`).join('')}</div></details>`:''}<div class="list">${rows.map(r=>record('fuel',r)).join('')||'<p class="muted">Zatiaľ žiadne tankovania pre toto auto.</p>'}</div></section>`;
}
function listPage(type){if(type==='expenses')return finance();if(type==='shopping')return shoppingPage();if(['cards','identities','files'].includes(type))return visualPage(type);let rows=getRecords(type).filter(r=>Object.values(r).filter(v=>typeof v==='string').join(' ').toLowerCase().includes(query.toLowerCase()));if(type==='notes')rows.sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned));if(['tasks','shopping'].includes(type))rows.sort((a,b)=>Number(!!a.done)-Number(!!b.done));if(type==='expenses')rows=rows.filter(r=>r.date?.startsWith(financeMonth));if(type==='expenses')rows.sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<div class="row between"><div><div class="eyebrow">${secure.includes(type)?'Odomknutý trezor':'Tvoj osobný priestor'}</div><h1>${title(type)}</h1></div><button class="gold" data-action="new" data-type="${type}">＋ Pridať</button></div>${secure.includes(type)?'<button class="quiet" data-action="vaultLock">⚿ Zamknúť trezor</button>':''}${type==='expenses'?finance():''}<div class="search"><input id="search" type="search" placeholder="Hľadať v sekcii…" aria-label="Hľadať v sekcii" value="${esc(query)}"></div><div id="records">${rows.length?rows.map(r=>record(type,r)).join(''):`<div class="empty"><span class="icon">${icon(type)}</span><h2>${query?'Žiadne výsledky':'Tu sa začína poriadok.'}</h2><p>${query?'Skús iný výraz.':'Pridaj svoj prvý záznam.'}</p></div>`}</div>${type==='expenses'&&data.service.length?'<h2>Náklady zo servisnej histórie</h2>'+data.service.filter(s=>Number(s.amount)>0&&s.date?.startsWith(financeMonth)).map(s=>record('service',s)).join(''):''}${type==='cars'?`${fuelSection()}<div class="row between"><h2>Servisná história</h2><button data-action="new" data-type="service">＋ Servis</button></div>${[...data.service].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(r=>record('service',r)).join('')}${!data.cars.length?'<p class="muted">Najskôr pridaj auto, potom jeho opravy a termíny.</p>':''}`:''}`;}
function vaultGate(){const setup=!data.vault;return `<div class="auth" style="padding-top:30px"><div class="brandbox"><span class="icon" style="font-size:38px;color:var(--gold)">⚿</span></div><div class="eyebrow">Súkromie navyše</div><h1>${setup?'Vytvor svoj trezor':'Trezor je zamknutý'}</h1><p class="muted">Heslá, doklady a dokumenty chráni samostatné heslo.</p><form id="vaultForm"><label for="vaultPassword">${setup?'Nové heslo (aspoň 12 znakov)':'Heslo trezoru'}</label><input id="vaultPassword" name="secret" type="password" minlength="12" autocomplete="${setup?'new-password':'current-password'}" required>${setup?'<label for="vaultConfirm">Zopakuj heslo</label><input id="vaultConfirm" name="confirm" type="password" minlength="12" autocomplete="new-password" required>':''}<p class="error" id="vaultError" role="alert"></p><button class="gold">${setup?'Vytvoriť trezor':'Odomknúť trezor'}</button></form><small>Zapamätaj si heslo. Bez neho sa obsah trezoru nedá obnoviť. Pri opustení appky sa automaticky zamkne.</small></div>`;}
function homeCustomize(){
 const ids=nav.filter(n=>n[0]!=='home').map(n=>n[0]),layout=homeSections(data.homeLayout,ids);
 show(`<div class="row between"><h2>Tvoj domov</h2><button data-action="close" aria-label="Zavrieť">×</button></div><p class="muted">Šípkami zmeníš poradie. Odškrtnutá sekcia sa skryje iba z domova. Zmeny sa ukladajú priebežne.</p><div class="home-editor">${layout.order.map((id,i)=>`<div class="home-editor-row"><label><input type="checkbox" aria-label="Zobraziť ${title(id)}" data-action="homeLayout" data-id="${id}" data-op="toggle" ${layout.hidden.includes(id)?'':'checked'} ${id==='settings'?'disabled':''}><span aria-hidden="true">${emojis[id]}</span><span>${title(id)}</span></label><div class="row"><button data-action="homeLayout" data-id="${id}" data-op="up" aria-label="Posunúť ${title(id)} nahor" ${i===0?'disabled':''}>↑</button><button data-action="homeLayout" data-id="${id}" data-op="down" aria-label="Posunúť ${title(id)} nadol" ${i===layout.order.length-1?'disabled':''}>↓</button></div></div>`).join('')}</div><div class="form-actions"><button data-action="homeLayout" data-op="reset">Obnoviť pôvodné</button><button class="gold" data-action="close">Hotovo</button></div>`);
}
function settings(){return `<div class="eyebrow">FSB / Nastavenia</div><h1>Tvoja appka.</h1><section class="card settings-block"><h3>Domov podľa teba</h3><p class="muted">Zmeň poradie kariet alebo skry tie, ktoré na domove nepotrebuješ. Všetky sekcie zostanú dostupné cez Viac.</p><button class="gold" data-action="homeCustomize">↕ Usporiadať domov</button></section><section class="card settings-block"><h3>Na plochu iPhonu</h3><p class="muted">Otvor link v Safari → Zdieľať → Pridať na plochu. Appka dostane čierno-zlatú ikonu FSB.</p></section><section class="card settings-block"><h3>Záloha a obnova</h3><p class="muted">Záloha obsahuje všetky údaje vrátane príloh, zašifrované tvojím PIN-om a heslom trezoru. Nie je to synchronizácia.</p><div class="row wrap"><button class="gold" data-action="backup">Stiahnuť zálohu</button><button data-action="restore">Obnoviť zálohu</button></div></section><section class="card settings-block"><h3>Zabezpečenie</h3><p class="muted">Appka sa zamkne po 5 minútach nečinnosti alebo pri prepnutí do pozadia. Šesťciferný PIN má obmedzenú ochranu proti skúšaniu offline; citlivé údaje ukladaj do trezoru.</p><button data-action="changePin">Zmeniť PIN</button><h3 style="margin-top:24px">Face ID / prístupový kľúč</h3><p class="muted">${faceRecord?'Zapnuté pre túto appku.':'Odomkni appku systémovým overením na podporovanom iPhone.'} iOS môže použiť Face ID alebo kód zariadenia. Trezor naďalej vyžaduje svoje heslo.</p>${faceRecord?'<button data-action="faceDisable">Vypnúť Face ID v appke</button>':'<button data-action="faceSetup">Nastaviť Face ID</button>'}<p class="mini muted">Vyžaduje podporu šifrovania cez prístupový kľúč (PRF). Ak chýba, zostane dostupný PIN. Nastavenie sa neprenáša v zálohe.</p></section><section class="card settings-block"><h3>Ukladanie v zariadení</h3><p class="muted">Žiadny účet, server ani automatický cloud. Vymazanie dát Safari alebo zmena adresy webu môže zneprístupniť údaje. Pravidelne zálohuj. Limit jednej prílohy je 8 MB, celkový limit dát appky 60 MB.</p><p class="muted">Pripomienky termínov sa zobrazujú v appke. Push upozornenia pri zatvorenej appke ešte nie sú zapojené.</p><span class="tag">FSB 1.5 · lokálna verzia</span></section>`;}
function render(){if(!data)return renderAuth();const content=page==='home'?home():page==='calendar'?calendar():page==='settings'?settings():page==='more'?`<div class="eyebrow">Všetko na jednom mieste</div><h1>Tvoj priestor</h1><div class="tiles">${nav.filter(n=>n[0]!=='home').map(n=>button(n[0])).join('')}</div>`:secure.includes(page)&&!vaultData?vaultGate():listPage(page);app.innerHTML=`<header><div class="row"><span class="brand">FSB</span><span class="header-caption muted" style="font-size:12px;border-left:1px solid var(--line);padding-left:18px">OSOBNÝ PRIESTOR</span></div><button class="quiet" data-action="lock" aria-label="Zamknúť appku">⚿ <span style="font-size:12px">Zamknúť</span></button></header><div class="shell"><aside class="sidebar">${nav.map(([p,i,n])=>`<button data-page="${p}" class="${page===p?'active':''}"><span class="icon">${i}</span>${n}</button>`).join('')}</aside><main class="main">${content}</main></div><nav class="bottom" aria-label="Hlavné menu">${[['home','⌂','Domov'],['calendar','▦','Kalendár'],['quick','＋',''],['expenses','€','Financie'],['more','⋯','Viac']].map(([p,i,n])=>`<button ${p==='quick'?'data-action="quick"':`data-page="${p}"`} class="${p==='quick'?'add':page===p?'active':''}"><span class="icon">${i}</span>${n}</button>`).join('')}</nav>`;
 const fc=$('#fuelCar');if(fc)fc.onchange=()=>{fuelCarId=fc.value;render();};const fm=$('#financeMonth');if(fm)fm.onchange=()=>{if(fm.value){financeMonth=fm.value;render();}};
 const search=$('#search');if(search)search.oninput=()=>{const pos=search.selectionStart;query=search.value;render();$('#search').focus();try{$('#search').setSelectionRange(pos,pos);}catch{}};
 const vf=$('#vaultForm');if(vf)vf.onsubmit=async e=>{e.preventDefault();const token=epoch;vf.querySelector('button').disabled=true;try{const secret=vf.secret.value;if(!data.vault){if(secret!==vf.confirm.value)throw Error('Heslá sa nezhodujú.');const result=await createEnvelope({passwords:[],identities:[],files:[]},secret);if(token!==epoch)return;vaultKey=result.key;vaultSalt=result.envelope.salt;vaultData={passwords:[],identities:[],files:[]};const next={...data,vault:result.envelope};const saved=await persist(next);if(token!==epoch)return;data=saved;}else{const k=await derive(secret,data.vault.salt);const v=await open(data.vault,k);if(!['passwords','identities','files'].every(t=>Array.isArray(v[t])))throw Error();if(token!==epoch)return;vaultKey=k;vaultSalt=data.vault.salt;vaultData=v;}if(token!==epoch){vaultData=null;vaultKey=null;return;}vf.reset();render();}catch(err){if(token===epoch){$('#vaultError').textContent=err.message==='Heslá sa nezhodujú.'?err.message:'Nesprávne heslo alebo sa trezor nepodarilo uložiť.';vf.querySelector('button').disabled=false;}}};}
function fieldHtml([name,label,type,required,options],r){let val=r[name]??'';const id='f_'+name,attrs=`id="${id}" name="${name}" ${required&&!r[name]?'required':''}`;if(type==='select'||type==='cars'||type==='shoppingLists'){const opts=type==='shoppingLists'?data.shoppingLists.map(l=>[l.id,l.title]):type==='cars'?data.cars.map(c=>[c.id,c.title]):options.map(o=>[o,o]);return `<label for="${id}">${label}</label><select ${attrs}>${opts.map(([v,t])=>`<option value="${esc(v)}" ${val===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`;}if(type==='checkbox')return `<label class="row"><input ${attrs} type="checkbox" ${val?'checked':''}>${label}</label>`;if(type==='file')return `<label for="${id}">${label}</label><input ${attrs} type="file" accept="${name==='logo'?'image/jpeg,image/png,image/webp':'image/jpeg,image/png,image/webp,image/heic,application/pdf'}">${val?`<small>Uložené: ${esc(val.name)}. Nový súbor nahradí pôvodný.</small><label class="row"><input type="checkbox" name="remove_${name}">Odstrániť prílohu</label>`:''}`;return `<label for="${id}">${label}</label>${type==='textarea'?`<textarea ${attrs}>${esc(val)}</textarea>`:`<input ${attrs} type="${type}" value="${esc(val)}" ${type==='number'?'min="0" max="999999999" step="0.01"':''} ${type==='password'?'autocomplete="new-password"':''}>`}`;}
async function fileData(file){if(file.size>8*1024*1024)throw Error('Jedna príloha môže mať najviac 8 MB.');if(!['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf'].includes(file.type))throw Error('Podporované sú JPG, PNG, WebP, HEIC a PDF.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,data:reader.result});reader.onerror=()=>reject(Error('Súbor sa nepodarilo načítať.'));reader.readAsDataURL(file);});}
function edit(type,id,defaults={}){if(type==='shopping'&&!data.shoppingLists.length)return edit('shoppingLists',null);if(['service','fuel'].includes(type)&&!data.cars.length){toast('Najprv pridaj auto.');return;}const old=id?getRecords(type).find(r=>r.id===id):null;const r=old||{date:today(),kind:'Mesačná platba',start:financeMonth,day:'1',category:type==='events'?'Osobné':'',color:'#74bfa0',...(type==='fuel'?{carId:fuelCarId||data.cars[0]?.id,title:'Tankovanie'}:{}),...defaults};show(`<div class="row between"><h2>${old?'Upraviť':'Pridať'} · ${title(type)}</h2><button data-action="close" aria-label="Zavrieť">×</button></div><form id="recordForm">${schemas[type].map(f=>fieldHtml(f,r)).join('')}${type==='recurring'?'<p class="note">Pri splátke zadaj celkovú zostávajúcu sumu na začiatku evidencie, vrátane dohodnutých poplatkov. Appka od nej odpočíta tvoje označené úhrady; úroky sama nepočíta. Pri úprave nezadávaj už znížený zostatok.</p>':''}${type==='passwords'?'<button type="button" data-action="generate" style="margin-top:12px">Vygenerovať silné heslo</button>':''}<p class="error" id="formError" role="alert"></p><div class="form-actions"><button type="button" data-action="close">Zrušiť</button><button class="gold">Uložiť</button></div></form>`);if(type==='fuel'){const info=document.createElement('p');info.className='note';info.id='fuelPrice';$('#recordForm').append(info);const update=()=>{const litres=Number($('#f_litres').value),amount=Number($('#f_amount').value);info.textContent=litres>0&&amount>0?'Cena za liter: '+(amount/litres).toLocaleString('sk-SK',{minimumFractionDigits:3,maximumFractionDigits:3})+' €/l':'';};$('#f_litres').oninput=update;$('#f_amount').oninput=update;update();}if(type==='recurring'){const toggle=()=>{const field=$('#f_balance'),isLoan=$('#f_kind').value==='Splátka';field.hidden=!isLoan;field.required=isLoan;field.previousElementSibling.hidden=!isLoan;};$('#f_kind').onchange=toggle;toggle();}if(type==='events')$('#f_category').onchange=()=>{$('#f_color').value=colors[$('#f_category').value];};$('#recordForm').onsubmit=async e=>{e.preventDefault();const token=epoch,form=e.currentTarget;form.querySelector('button.gold').disabled=true;try{const f=new FormData(form),record={...r,id:old?.id||crypto.randomUUID(),updatedAt:new Date().toISOString()};for(const [name,,kind,required]of schemas[type]){if(kind==='file'){if(f.get('remove_'+name))delete record[name];const file=f.get(name);if(file?.size){if(name==='logo'&&!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Logo musí byť JPG, PNG alebo WebP.');record[name]=await fileData(file);}if(required&&!record[name])throw Error('Pridaj prílohu.');}else record[name]=kind==='checkbox'?f.has(name):String(f.get(name)||'').trim();if(required&&kind!=='file'&&!record[name])throw Error('Vyplň povinné polia.');}if(type==='fuel'){record.title=record.title||'Tankovanie';validateFuelRecord(record,data.fuel||[],data.cars);}if(type==='recurring'&&(!Number.isInteger(Number(record.day))||Number(record.day)<1||Number(record.day)>31))throw Error('Deň splatnosti musí byť 1 až 31.');if(type==='recurring'&&Number(record.amount)<=0)throw Error('Mesačná suma musí byť väčšia ako nula.');if(type==='recurring'&&record.kind==='Splátka'&&Number(record.balance)<=0)throw Error('Zadaj sumu, ktorú ešte ostáva splatiť od začiatku evidencie.');if(type==='recurring'&&record.end&&record.end<record.start)throw Error('Koniec nemôže byť pred začiatkom.');if(token!==epoch)return;const next=structuredClone(data),vNext=vaultData?structuredClone(vaultData):null, target=secure.includes(type)?vNext:next;if(type==='shoppingLists'){const lines=shoppingLines(record.items);if(lines.length>200)throw Error('Naraz môžeš pridať najviac 200 položiek.');for(const title of lines)next.shopping.push({id:crypto.randomUUID(),listId:record.id,title,quantity:'',done:false});delete record.items;}const index=target[type].findIndex(x=>x.id===record.id);if(index<0)target[type].push(record);else target[type][index]=record;if(JSON.stringify(next).length+JSON.stringify(vNext).length>60*1024*1024)throw Error('Dosiahnutý limit 60 MB. Odstráň nepotrebné prílohy.');const saved=await persist(next,vNext);if(token!==epoch)return;data=saved;vaultData=vNext;closeModal();render();if(type==='shoppingLists')shoppingView(record.id);else if(type==='shopping')shoppingView(record.listId);toast('Uložené.');}catch(err){if(token===epoch){$('#formError').textContent=err.message||'Ukladanie zlyhalo. Skús zálohu a skontroluj miesto v zariadení.';form.querySelector('button.gold').disabled=false;}}};}
function attachment(a){if(!a?.data?.startsWith('data:'))return '';const allowed=['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf'];if(!allowed.includes(a.type))return '';const split=a.data.indexOf(',');const bytes=Uint8Array.from(atob(a.data.slice(split+1)),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:a.type}));urls.push(url);return `${['image/jpeg','image/png','image/webp'].includes(a.type)?`<img class="attachment" src="${url}" alt="${esc(a.name)}">`:''}<a class="filelink" href="${url}" download="${esc(a.name)}">Stiahnuť ${esc(a.name)}</a>`;}
function view(type,id){if(type==='shoppingLists')return shoppingView(id);const r=getRecords(type).find(r=>r.id===id);if(!r)return;show(`<div class="row between"><h2>${esc(r.title)}</h2><button data-action="close" aria-label="Zavrieť">×</button></div><div id="details"></div><div class="form-actions">${type==='shopping'?`<button data-action="view" data-type="shoppingLists" data-id="${esc(r.listId)}">← Zoznam</button>`:''}${type==='payments'?`<button data-action="unpay" data-id="${esc(id)}">Vrátiť na neuhradené</button>`:`<button data-action="edit" data-type="${type}" data-id="${esc(id)}">Upraviť</button>`}<button class="danger" data-action="delete" data-type="${type}" data-id="${esc(id)}">Vymazať</button></div>`);$('#details').innerHTML=schemas[type].filter(([n])=>r[n]&&n!=='title'&&!(type==='cards'&&n==='logo')).map(([n,label,kind])=>`<div class="view-field"><small>${label}</small>${kind==='file'?attachment(r[n]):kind==='password'?'<input type="password" id="revealedPassword" readonly aria-label="Uložené heslo"><div class="row wrap" style="margin-top:10px"><button data-action="reveal">Zobraziť / skryť</button><button class="gold" data-action="copyPassword">📋 Skopírovať heslo</button></div>':`<div class="view-text">${esc(kind==='shoppingLists'?data.shoppingLists.find(l=>l.id===r[n])?.title||'Zoznam':kind==='cars'?data.cars.find(c=>c.id===r[n])?.title||'Auto':kind==='date'?fmt(r[n]):kind==='checkbox'?'Áno':r[n])}</div>`}</div>`).join('');if($('#revealedPassword'))$('#revealedPassword').value=r.password;}
function day(date){const rows=data.events.filter(r=>r.date===date).sort((a,b)=>(a.time||'').localeCompare(b.time||''));show(`<div class="row between"><h2>${fmt(date)}</h2><button data-action="close" aria-label="Zavrieť">×</button></div>${rows.map(r=>record('events',r)).join('')||'<p class="muted">Zatiaľ bez plánov.</p>'}<button class="gold" data-action="new" data-type="events" data-date="${date}">＋ Pridať udalosť</button>`);}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function restore(){show(`<h2>Obnoviť zálohu</h2><p class="muted">Obnova nahradí všetky aktuálne údaje. Najprv si ich zálohuj. Použi PIN, ktorým bola záloha vytvorená.</p><form id="restoreForm"><label>Záloha FSB<input name="file" type="file" accept=".json,application/json" required></label><label>PIN zálohy<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{6}" required></label><label class="row"><input name="confirm" type="checkbox" required>Súhlasím s nahradením údajov</label><p class="error" id="restoreError"></p><div class="form-actions"><button type="button" data-action="close">Zrušiť</button><button class="gold">Obnoviť</button></div></form>`);$('#restoreForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,token=epoch;form.querySelector('.gold').disabled=true;try{if(form.file.files[0].size>100*1024*1024)throw Error();const imported=JSON.parse(await form.file.files[0].text());if(!validEnvelope(imported))throw Error();const k=await derive(form.pin.value,imported.salt);validateData(await open(imported,k));if(token!==epoch)return;await writeQueue.catch(()=>{});await store('readwrite',s=>{s.delete('face');return s.put(imported,'main');});faceRecord=null;envelope=imported;lock();toast('Záloha obnovená. Odomkni PIN-om zálohy.');}catch{if(token===epoch){$('#restoreError').textContent='Neplatná záloha, nesprávny PIN alebo chyba ukladania.';form.querySelector('.gold').disabled=false;}}};}
async function changePin(){show(`<h2>Zmeniť PIN</h2><form id="pinForm"><label>Aktuálny PIN<input name="old" type="password" pattern="[0-9]{6}" inputmode="numeric" required></label><label>Nový 6-ciferný PIN<input name="fresh" type="password" pattern="[0-9]{6}" inputmode="numeric" required></label><label>Zopakuj nový PIN<input name="confirm" type="password" pattern="[0-9]{6}" inputmode="numeric" required></label><p class="error" id="pinError"></p><div class="form-actions"><button type="button" data-action="close">Zrušiť</button><button class="gold">Zmeniť</button></div></form>`);$('#pinForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,token=epoch;f.querySelector('.gold').disabled=true;try{if(f.fresh.value!==f.confirm.value)throw Error();const oldKey=await derive(f.old.value,envelope.salt);await open(envelope,oldKey);const result=await createEnvelope(data,f.fresh.value);if(token!==epoch)return;await writeQueue.catch(()=>{});await store('readwrite',s=>{s.delete('face');return s.put(result.envelope,'main');});faceRecord=null;envelope=result.envelope;if(token!==epoch)return;key=result.key;closeModal();render();toast('PIN zmenený. Face ID nastav znova a vytvor zálohu.');}catch{if(token===epoch){$('#pinError').textContent='Over aktuálny PIN aj zhodu nových PIN-ov.';f.querySelector('.gold').disabled=false;}}};}
function faceSetup(){
 show(`<h2>Zapnúť Face ID</h2><p class="muted">Vytvoríš prístupový kľúč FSB a následne potvrdíš odomykanie. Použi systémové Heslá na iPhone. Ak zariadenie nepodporuje potrebné šifrovanie, appka zostane pri PIN-e.</p><p class="note">PIN si ponechaj. Obnova zálohy a samostatný trezor ho nenahrádzajú.</p><div class="form-actions"><button data-action="close">Zrušiť</button><button class="gold" id="faceCreate">Vytvoriť kľúč</button></div>`);
 $('#faceCreate').onclick=async()=>{
  if(faceBusy)return;const salt=envelope.salt;lock();const token=epoch;faceBusy=true;
  try{
   const registration=await registerPasskey(salt);if(token!==epoch)return;
   show(`<h2>Dokončiť Face ID</h2><p class="muted">Zadaj svoj aktuálny PIN. Potom ešte raz potvrdíš prístupový kľúč. PIN sa uloží iba zašifrovaný týmto kľúčom.</p><form id="faceFinish"><label>Aktuálny PIN<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="off" required></label><p class="error" id="faceError"></p><div class="form-actions"><button type="button" data-action="close">Zrušiť</button><button class="gold">Overiť PIN</button></div></form>`);
   $('#faceFinish').onsubmit=async e=>{
    e.preventDefault();const f=e.currentTarget;let pin=f.pin.value;f.querySelector('.gold').disabled=true;
    try{
     const k=await derive(pin,envelope.salt);await open(envelope,k);if(token!==epoch)return;
     f.reset();show(`<h2>Posledné potvrdenie</h2><p class="muted">Potvrď prístupový kľúč FSB. Tým sa zapne odomykanie cez Face ID alebo kód zariadenia.</p><div class="form-actions"><button data-action="close">Zrušiť</button><button class="gold" id="faceConfirm">Potvrdiť a zapnúť</button></div>`);
     $('#faceConfirm').onclick=async()=>{
      if(faceBusy)return;closeModal();faceBusy=true;
      try{const protectedPin=await protectPin(registration,pin);if(token!==epoch||envelope.salt!==salt)return;await store('readwrite',s=>s.put(protectedPin,'face'));faceRecord=protectedPin;if(token===epoch){renderAuth();toast('Face ID nastavené. Teraz ním môžeš odomknúť appku.');}}
      catch(err){if(token===epoch){renderAuth();$('#authError').textContent=passkeyError(err);}}
      finally{pin='';faceBusy=false;}
     };
    }catch{pin='';if(token===epoch&&$('#faceError')){$('#faceError').textContent='Nesprávny PIN. Skús znova.';f.querySelector('.gold').disabled=false;}}
   };
  }catch(err){if(token===epoch){renderAuth();$('#authError').textContent=passkeyError(err);}}
  finally{faceBusy=false;}
 };
}
async function faceUnlock(button){
 if(faceBusy||!faceRecord)return;$('#authForm')?.reset();const token=epoch;faceBusy=true;button.disabled=true;
 try{const pin=await recoverPin(faceRecord,envelope.salt);const k=await derive(pin,envelope.salt);const decoded=validateData(await open(envelope,k));if(token!==epoch||document.hidden)return;key=k;data=decoded;lastActivity=Date.now();page='home';render();}
 catch(err){if(token===epoch&&$('#authError'))$('#authError').textContent=passkeyError(err);}
 finally{faceBusy=false;button.disabled=false;}
}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action],[data-page]');if(!el){const card=event.target.closest('[data-open]');if(card&&data)view(card.dataset.open,card.dataset.id);return;}lastActivity=Date.now();if(el.dataset.page){if(!data)return;closeModal();page=el.dataset.page;if(page==='shopping')shoppingListId=null;query='';if(page!=='calendar')document.body.classList.remove('full-cal');render();window.scrollTo(0,0);return;}const {action,type,id,date}=el.dataset;try{if(action==='close')return closeModal();if(action==='restore')return restore();if(action==='lock')return lock();if(action==='faceUnlock')return faceUnlock(el);if(!data)return;if(action==='homeCustomize')return homeCustomize();if(action==='homeLayout'){if(mutationBusy){homeCustomize();toast('Počkaj na uloženie zmeny.');return;}el.disabled=true;const token=epoch,next=structuredClone(data),ids=nav.filter(n=>n[0]!=='home').map(n=>n[0]);next.homeLayout=el.dataset.op==='reset'?homeSections(null,ids):changeHomeLayout(data.homeLayout,ids,id,el.dataset.op);try{const saved=await persist(next);if(token!==epoch)return;data=saved;render();homeCustomize();}catch(err){if(token===epoch){homeCustomize();toast('Zmenu sa nepodarilo uložiť.');}}return;}if(action==='faceSetup')return faceSetup();if(action==='faceDisable'){await store('readwrite',s=>s.delete('face'));faceRecord=null;render();toast('Face ID vypnuté. Prístupový kľúč môžeš odstrániť aj v Heslách na iPhone.');return;}if(action==='new')return edit(type,null,{...(date?{date}:{}),...(el.dataset.kind?{kind:el.dataset.kind}:{})});if(action==='edit')return edit(type,id);if(action==='view')return view(type,id);if(action==='shoppingBack'){shoppingListId=null;closeModal();render();return;}if(action==='day')return day(date);if(action==='quick')return show(`<div class="row between"><h2>Čo chceš pridať?</h2><button data-action="close" aria-label="Zavrieť">×</button></div><div class="tiles">${['events','notes','expenses','tasks','shopping','service'].map(t=>`<button class="tile" data-action="new" data-type="${t}"><span class="icon">${icon(t)}</span>${title(t)}</button>`).join('')}</div>`);if(action==='financeTab'){financeTab=el.dataset.tab;query='';render();return;}if(action==='prev'||action==='next'){month=new Date(month.getFullYear(),month.getMonth()+(action==='prev'?-1:1),1);return render();}if(action==='today'){month=new Date(new Date().getFullYear(),new Date().getMonth(),1);return render();}if(action==='fullscreen')return document.body.classList.toggle('full-cal');if(action==='vaultLock'){vaultData=null;vaultKey=null;vaultSalt=null;return render();}if(action==='copyPassword'){const value=$('#revealedPassword')?.value;if(!value)return;try{await navigator.clipboard.writeText(value);toast('Heslo skopírované do schránky.');}catch{toast('Kopírovanie nie je povolené. Zobraz heslo a skopíruj ho ručne.');}return;}if(action==='reveal'){const input=$('#revealedPassword');input.type=input.type==='password'?'text':'password';return;}if(action==='generate'){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*';let generated='';while(generated.length<20){for(const b of crypto.getRandomValues(new Uint8Array(32)))if(b<Math.floor(256/chars.length)*chars.length&&generated.length<20)generated+=chars[b%chars.length];}$('#f_password').value=generated;toast('Nové heslo je vo formulári. Ulož záznam.');return;}if(action==='backup'){const token=epoch;await writeQueue;if(token!==epoch)return;download(new Blob([JSON.stringify(envelope)],{type:'application/json'}),`FSB-zaloha-${today()}.json`);return toast('Záloha pripravená na stiahnutie.');}if(action==='unpay'){el.disabled=true;const token=epoch,next=structuredClone(data);next.payments=next.payments.filter(p=>p.id!==id);const saved=await persist(next);if(token!==epoch)return;data=saved;closeModal();render();toast('Platba je znova neuhradená.');return;}if(action==='pay'){
 const r=data.recurring.find(r=>r.id===id);const amount=recurringDue(r,data.payments,financeMonth);if(amount<=0)return;if(data.payments.some(p=>p.month===financeMonth&&p.recurringId===id))return;el.disabled=true;const token=epoch,next=structuredClone(data);next.payments.push({id:crypto.randomUUID(),recurringId:id,title:r.title,amount:String(amount),category:r.category,month:financeMonth,date:financeMonth===today().slice(0,7)?today():financeMonth+'-01'});const saved=await persist(next);if(token===epoch){data=saved;render();toast('Platba označená ako zaplatená.');}return;
 }if(action==='changePin')return changePin();if(action==='delete'){if(type==='cars'&&(data.service.some(s=>s.carId===id)||(data.fuel||[]).some(s=>s.carId===id))){toast('Najprv odstráň servisné záznamy a tankovania tohto auta.');return;}show(`<h2>Vymazať záznam?</h2><p class="muted">${type==='shoppingLists'?'Vymaže sa zoznam aj všetky jeho položky.':'Vymazanie je trvalé. Záznam obnovíš iba zo svojej zálohy.'}</p><div class="form-actions"><button data-action="close">Zrušiť</button><button class="danger" data-action="confirmDelete" data-type="${type}" data-id="${esc(id)}">Vymazať</button></div>`);return;}if(action==='confirmDelete'||action==='toggle'){if(mutationBusy){if(action==='toggle')el.checked=!!getRecords(type).find(r=>r.id===id)?.done;toast('Ukladám predchádzajúcu zmenu.');return;}el.disabled=true;const token=epoch,next=structuredClone(data),vNext=vaultData?structuredClone(vaultData):null,target=secure.includes(type)?vNext:next;const shoppingParent=type==='shopping'?target.shopping.find(i=>i.id===id)?.listId:null;const wasShoppingDialog=type==='shopping'&&modal.open;if(action==='confirmDelete'){target[type]=target[type].filter(r=>r.id!==id);if(type==='shoppingLists')next.shopping=next.shopping.filter(i=>i.listId!==id);}else{const r=target[type].find(r=>r.id===id);r.done=!r.done;}const saved=await persist(next,vNext);if(token!==epoch)return;data=saved;vaultData=vNext;closeModal();render();if(wasShoppingDialog&&shoppingParent)shoppingView(shoppingParent);}}catch(err){toast('Operácia sa nepodarila. '+(err.message||''));el.disabled=false;}});
document.addEventListener('input',()=>lastActivity=Date.now());
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(data||modal.open||$('#authForm')?.pin.value)lock();}});
window.addEventListener('pagehide',()=>{if(data)lock();});
setInterval(()=>{if(data&&Date.now()-lastActivity>300000)lock();},10000);
async function start(){try{if(!crypto.subtle)throw Error('Otvor appku cez HTTPS alebo localhost.');db=await new Promise((resolve,reject)=>{const request=indexedDB.open('fsb-private-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('state');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});envelope=await store('readonly',s=>s.get('main'));faceRecord=await store('readonly',s=>s.get('face'));if(faceRecord?.envelopeSalt!==envelope?.salt)faceRecord=null;renderAuth();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(err){app.innerHTML=`<div class="auth"><h1>FSB sa nepodarilo otvoriť</h1><p>${esc(err.message)}</p><p class="muted">Použi Safari cez HTTPS a povoľ ukladanie dát.</p></div>`;}}
start();






